import { useState, type FormEvent } from 'react';
import { JxAlert, JxButton, JxDivider, JxInputField, JxStepper, JxTable } from '@jinx-ui/react';

export interface SignupValues {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
}

export interface SignupWizardProps {
  onSubmit: (values: SignupValues) => void | Promise<void>;
}

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const EMPTY: SignupValues = { name: '', email: '', phone: '', city: '', street: '', zip: '' };

function validate(step: number, values: SignupValues): Partial<Record<keyof SignupValues, string>> {
  const errors: Partial<Record<keyof SignupValues, string>> = {};
  if (step === 0) {
    if (!values.name.trim()) errors.name = 'Укажите имя и фамилию';
    if (!values.email.includes('@')) errors.email = 'Укажите адрес с символом @';
    if (values.phone.replace(/\D/g, '').length < 10) errors.phone = 'Укажите номер из 10 цифр';
  }
  if (step === 1) {
    if (!values.city.trim()) errors.city = 'Укажите город';
    if (!values.street.trim()) errors.street = 'Укажите улицу и дом';
    if (!/^\d{6}$/.test(values.zip)) errors.zip = 'Индекс состоит из 6 цифр';
  }
  return errors;
}

export default function SignupWizard({ onSubmit }: SignupWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<SignupValues>(EMPTY);
  const [errors, setErrors] = useState<Partial<Record<keyof SignupValues, string>>>({});
  const [sending, setSending] = useState(false);
  const [failed, setFailed] = useState(false);

  const isLast = step === STEPS.length - 1;

  const set = (key: keyof SignupValues) => (event: { target: { value: string } }) => {
    setValues((prev) => ({ ...prev, [key]: event.target.value }));
    setErrors((prev) => ({ ...prev, [key]: undefined }));
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const found = validate(step, values);
    if (Object.keys(found).length > 0) {
      setErrors(found);
      return;
    }
    if (!isLast) {
      setStep(step + 1);
      return;
    }
    setSending(true);
    setFailed(false);
    try {
      await onSubmit(values);
    } catch {
      setFailed(true);
    } finally {
      setSending(false);
    }
  };

  const summary: Array<[string, string]> = [
    ['Имя', values.name],
    ['Почта', values.email],
    ['Телефон', values.phone],
    ['Город', values.city],
    ['Улица и дом', values.street],
    ['Индекс', values.zip],
  ];

  return (
    <form
      onSubmit={handleSubmit}
      noValidate
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 20,
        maxWidth: 520,
        padding: 24,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <JxStepper steps={STEPS} current={step} />
      <JxDivider />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          <JxInputField
            label="Имя и фамилия"
            required
            autoFocus
            value={values.name}
            onChange={set('name')}
            errorText={errors.name}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={values.email}
            onChange={set('email')}
            errorText={errors.email}
            helperText="На этот адрес придёт письмо с подтверждением"
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            required
            value={values.phone}
            onChange={set('phone')}
            errorText={errors.phone}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          <JxInputField
            label="Город"
            required
            autoFocus
            value={values.city}
            onChange={set('city')}
            errorText={errors.city}
          />
          <JxInputField
            label="Улица и дом"
            required
            value={values.street}
            onChange={set('street')}
            errorText={errors.street}
          />
          <JxInputField
            label="Почтовый индекс"
            inputMode="numeric"
            required
            value={values.zip}
            onChange={set('zip')}
            errorText={errors.zip}
            helperText="Шесть цифр, например 101000"
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          <JxAlert title="Проверьте данные перед отправкой" intent="info">
            Вернуться и исправить можно кнопкой «Назад».
          </JxAlert>
          <JxTable>
            <tbody>
              {summary.map(([label, value]) => (
                <tr key={label}>
                  <th scope="row" style={{ textAlign: 'left', color: 'var(--jx-text-2)', whiteSpace: 'nowrap' }}>
                    {label}
                  </th>
                  <td style={{ wordBreak: 'break-word' }}>{value}</td>
                </tr>
              ))}
            </tbody>
          </JxTable>
          {failed && (
            <JxAlert title="Не удалось отправить заявку" intent="danger">
              Проверьте соединение и попробуйте ещё раз.
            </JxAlert>
          )}
        </div>
      )}

      <JxDivider />
      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 8 }}>
        <JxButton
          type="button"
          variant="ghost"
          disabled={step === 0 || sending}
          onClick={() => {
            setErrors({});
            setStep(step - 1);
          }}
        >
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary" disabled={sending}>
          {isLast ? (sending ? 'Отправляем…' : 'Отправить') : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

